function Counter() {
  const [count, setCount] = useState(1);
  const [items, setItems] = useState([
    { id: 'b', text: 'Bread' },
    { id: 'm', text: 'Milk' },
  ]);

  function handleClick() {
    setCount((c) => c + 1);                                  // both updates are batched
    setItems((prev) => [{ id: 'e', text: 'Eggs' }, ...prev]); // into ONE re-render
  }

  return (
    <div className="card">
      <h1>Count: {count}</h1>
      {count % 2 === 0 ? <span>even</span> : <p>odd</p>}
      <ul>
        {items.map((item) => <li key={item.id}>{item.text}</li>)}
      </ul>
      <button onClick={handleClick}>Add</button>
    </div>
  );
}

function ChatRoom({ roomId }) {
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    const connection = createConnection(roomId);   // e.g. a WebSocket
    connection.connect();
    connection.on('message', (msg) => setMessages((prev) => [...prev, msg]));

    return () => {
      connection.disconnect();                     // cleanup: undo what the effect did
    };
  }, [roomId]);                                    // re-run only when roomId changes

  return <MessageList messages={messages} />;
}

// The three forms of the dependency array:
// useEffect(fn);          -> after EVERY commit
// useEffect(fn, []);      -> after the FIRST commit only (cleanup on unmount)
// useEffect(fn, [a, b]);  -> after commits where a or b changed (compared with Object.is)

function TodoList() {
  const [todos, setTodos] = useState([
    { id: 'm', text: 'Milk' },
    { id: 'e', text: 'Eggs' },
  ]);
  const addBread = () => setTodos((prev) => [{ id: 'b', text: 'Bread' }, ...prev]);

  return (
    <>
      <button onClick={addBread}>Add Bread at the top</button>
      <ul>
        {todos.map((todo, index) => (
          // BAD:  key={index}   -> identity follows the position
          // GOOD: key={todo.id} -> identity follows the data
          <TodoRow key={todo.id} text={todo.text} />
        ))}
      </ul>
    </>
  );
}

