    </div>
  );
}

function useFetch(url) {
  const [result, setResult] = useState({ url: null, data: null, error: null });

  useEffect(() => {
    const controller = new AbortController();
    fetch(url, { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((data) => setResult({ url, data, error: null }))
      .catch((error) => {
        if (error.name !== 'AbortError') setResult({ url, data: null, error });
      });
    return () => controller.abort();   // cancel the old request (url changed / unmount)
  }, [url]);

  const loading = result.url !== url;  // derived during render, no extra state
  return { data: loading ? null : result.data, error: loading ? null : result.error, loading };
}

