// 1) Local state: useReducer for several related transitions
function cartReducer(state, action) {
  switch (action.type) {
    case 'add':
      return { ...state, items: [...state.items, action.item] };
    case 'clear':
      return { ...state, items: [] };
    default:
      return state;
  }
}
function CartPage() {
  const [cart, dispatch] = useReducer(cartReducer, { items: [] });
  return <button onClick={() => dispatch({ type: 'clear' })}>Clear ({cart.items.length})</button>;
}

// 2) Shared client state: a Zustand store (no provider needed)
import { create } from 'zustand';
const useCartStore = create((set) => ({
  items: [],
  add: (item) => set((s) => ({ items: [...s.items, item] })),
}));
function CartBadge() {
  const count = useCartStore((s) => s.items.length);   // re-renders only when length changes
  return <span>{count}</span>;
}

// 3) Server state: TanStack Query (cache, dedupe, refetch, retries)
import { useQuery } from '@tanstack/react-query';
function Orders({ userId }) {
  const { data, isPending, error } = useQuery({
    queryKey: ['orders', userId],
    queryFn: () => fetch(`/api/users/${userId}/orders`).then((r) => r.json()),
    staleTime: 60_000,
  });
  if (isPending) return <p>Loading...</p>;
  if (error) return <p>Could not load orders</p>;
  return <p>{data.length} orders</p>;
}

